1	// A tiny todo list with due dates, priorities and JSON persistence.
2	import { readFileSync, writeFileSync } from "node:fs";
3	
4	export const PRIORITIES = ["low", "normal", "high"];
5	
6	function parseDue(due) {
7	  if (due === undefined || due === null) return null;
8	  const d = due instanceof Date ? due : new Date(due);
9	  if (Number.isNaN(d.getTime())) throw new Error("invalid due date");
10	  return d.toISOString();
11	}
12	
13	export class TodoList {
14	  constructor() { this.items = []; this.nextId = 1; }
15	
16	  add(title, { due, priority = "normal" } = {}) {
17	    if (!title) throw new Error("title is required");
18	    if (!PRIORITIES.includes(priority)) throw new Error(`invalid priority: ${priority}`);
19	    const item = { id: this.nextId++, title, done: false, due: parseDue(due), priority };
20	    this.items.push(item);
21	    return item;
22	  }
23	
24	  complete(id) {
25	    const item = this.items.find(i => i.id === id);
26	    if (!item) throw new Error(`item ${id} not found`);
27	    item.done = true;
28	    return item;
29	  }
30	
31	  pending() {
32	    return this.items.filter(i => !i.done);
33	  }
34	
35	  clear() {
36	    this.items = this.items.filter(i => !i.done);
37	  }
38	
39	  // Overdue first, then priority (high to low), then due date (none last), then id.
40	  sorted(now = new Date()) {
41	    const t = new Date(now).getTime();
42	    const overdue = i => !i.done && i.due !== null && new Date(i.due).getTime() < t;
43	    const dueTime = i => (i.due === null ? Infinity : new Date(i.due).getTime());
44	    return [...this.items].sort((a, b) =>
45	      overdue(b) - overdue(a) ||
46	      PRIORITIES.indexOf(b.priority) - PRIORITIES.indexOf(a.priority) ||
47	      (dueTime(a) === dueTime(b) ? 0 : dueTime(a) < dueTime(b) ? -1 : 1) ||
48	      a.id - b.id);
49	  }
50	
51	  save(path) {
52	    writeFileSync(path, JSON.stringify({ nextId: this.nextId, items: this.items }, null, 2));
53	  }
54	
55	  static load(path) {
56	    const data = JSON.parse(readFileSync(path, "utf8"));
57	    const list = new TodoList();
58	    list.items = data.items.map(i => ({
59	      done: false, due: null, priority: "normal", ...i,
60	    }));
61	    list.nextId = Math.max(data.nextId ?? 1, ...list.items.map(i => i.id + 1));
62	    return list;
63	  }
64	}
