import { test } from "node:test";
import assert from "node:assert/strict";
import { TodoList } from "../src/todo.js";

test("addTag normalizes and dedupes", () => {
  const list = new TodoList();
  const a = list.add("buy milk");
  list.addTag(a.id, "Home");
  list.addTag(a.id, " home ");
  assert.deepEqual(list.items[0].tags, ["home"]);
});

test("addTag validates input", () => {
  const list = new TodoList();
  const a = list.add("x");
  assert.throws(() => list.addTag(a.id, ""), /tag is required/);
  assert.throws(() => list.addTag(99, "t"), /not found/);
});

test("removeTag removes and tolerates missing tags", () => {
  const list = new TodoList();
  const a = list.add("x");
  list.addTag(a.id, "a");
  list.addTag(a.id, "b");
  list.removeTag(a.id, "A");
  list.removeTag(a.id, "zzz");
  assert.deepEqual(a.tags, ["b"]);
  assert.throws(() => list.removeTag(99, "a"), /not found/);
});

test("byTag filters items", () => {
  const list = new TodoList();
  const a = list.add("buy milk");
  list.add("walk dog");
  list.addTag(a.id, "home");
  assert.deepEqual(list.byTag("HOME").map(i => i.title), ["buy milk"]);
  assert.deepEqual(list.byTag("none"), []);
});

test("search matches title and tags case-insensitively, all terms", () => {
  const list = new TodoList();
  const a = list.add("Buy milk");
  const b = list.add("Walk dog");
  list.addTag(b.id, "outdoor");
  assert.deepEqual(list.search("MILK").map(i => i.id), [a.id]);
  assert.deepEqual(list.search("outdoor walk").map(i => i.id), [b.id]);
  assert.deepEqual(list.search("milk dog"), []);
  assert.deepEqual(list.search("  "), []);
});
